  $('#meetingStart',m.root).value=toLocalInput(Math.floor(startDefault.getTime()/1000));$('#meetingEnd',m.root).value=toLocalInput(Math.floor(endDefault.getTime()/1000));$('#mb',m.root).value=String(ctx.state.boot.settings.calendarMeetingBuffer||15);
  const createAt=async(st,en)=>{if(!st||!en||en<=st)return toast('O término deve ser posterior ao início.');m.close();const cals=await invoke('list_calendars');editEvent({id:0,calendar_id:cals.find(c=>!c.read_only)?.id||cals[0]?.id||0,uid:'',title:'Reunião',description:'',location:'',start_ts:st,end_ts:en,all_day:false,attendees:'',status:'CONFIRMED',rrule:'',source_message_id:null,video_url:'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone},cals)};
