 for(const [id,key] of r13fields){$('#'+id,p).onchange=async e=>{const account=$('#composeScope',p).value;await invoke('set_setting',{req:{key:account?`account.${account}.composition.${key}`:`composition.${key}`,value:String(e.target.checked)}});$('#composeSavedState',p).textContent='Salvo.'}};
