 if(kind==='sync'){p.innerHTML=`<h2>Sincronização</h2><p class="settingsPanelIntro">Configurações gerais de sincronização. As credenciais e servidores permanecem em Contas.</p><label class="settingsToggle"><input id="syncBackground" type="checkbox"> Sincronizar/verificar mensagens em background</label><div class="settingsRow"><span><b>Conta atual</b><small>${ctx.state.account?esc(ctx.state.boot.accounts.find(a=>a.id===ctx.state.account)?.email||'Conta selecionada'):'Nenhuma conta individual selecionada'}</small></span><button id="syncCurrentAccount" ${ctx.state.account?'':'disabled'}>Sincronizar agora</button></div><p class="dim">O TCS usa sincronização incremental e IMAP IDLE quando suportado. A sincronização em background pode ser desligada sem afetar a leitura e o envio manual.</p>`;$('#syncBackground',p).checked=!!ctx.state.boot.settings.background;if(/\bLinux\b/i.test(navigator.userAgent)){$('#syncBackground',p).checked=false;$('#syncBackground',p).disabled=true;$('#syncBackground',p).title='Desativado no Linux: nenhum serviço do TCS inicia sozinho.';}$('#syncBackground',p).onchange=async e=>{await invoke('set_background_enabled',{enabled:e.target.checked});ctx.state.boot.settings.background=e.target.checked};$('#syncCurrentAccount',p).onclick=async()=>{if(!ctx.state.account)return;const folder=ctx.state.folder?.startsWith('__')?'INBOX':(ctx.state.folder||'INBOX');try{await invoke('sync_recent',{accountId:ctx.state.account,folder});toast('Sincronização concluída.')}catch(e){toast(String(e))}}}
