 if(kind==='shortcuts'){const editable=Object.entries(SHORTCUTS).filter(([k])=>k!=='bold');p.innerHTML=`<h2>Atalhos</h2><p class="settingsPanelIntro">O TCS usa atalhos familiares do Outlook quando há função equivalente e sem conflito. Negrito é fixo em Ctrl+B no Composer e possui botão na barra de formatação; Ctrl+K pertence ao editor para inserir link; o Command Center usa Ctrl+Alt+K por padrão.</p><div id="shortcutConflict" class="shortcutConflict"></div><div class="shortcutEditor">${editable.map(([k,v])=>`<label class="settingsRow"><span><b>${esc(shortcutLabel(k))}</b><small>${esc(v.scope==='composer'?'Compositor':v.scope==='mail'?'E-mail':'Global')}${(v.aliasesPt||v.aliases||[]).length?` · aliases: ${esc((v.aliasesPt||v.aliases).join(' / '))}`:''}</small></span><input data-shortcut-input="${k}" value="${esc((ctx.state.boot.settings.shortcuts?.[k]||v.default)||'')}"></label>`).join('')}</div><div class="shortcutTable"><span><span>Excluir</span><kbd>Delete</kbd></span><span><span>Excluir definitivamente</span><kbd>Shift + Delete</kbd></span><span><span>Seleção por intervalo</span><kbd>Shift + ↑ / ↓</kbd></span><span><span>Alternar item individual</span><kbd>Ctrl + Espaço</kbd></span><span><span>Selecionar tudo</span><kbd>Ctrl + A</kbd></span></div><footer class="modalActions"><button id="resetShortcuts">Restaurar padrões</button><button id="saveShortcuts" class="primary">Salvar atalhos</button></footer>`;const collect=()=>Object.fromEntries($$('[data-shortcut-input]',p).map(i=>[i.dataset.shortcutInput,i.value.trim()]));$('#resetShortcuts',p).onclick=()=>{$$('[data-shortcut-input]',p).forEach(i=>i.value=SHORTCUTS[i.dataset.shortcutInput]?.default||'');$('#shortcutConflict',p).textContent=''};$('#saveShortcuts',p).onclick=async()=>{const candidate=collect(),conflicts=validateShortcutMap(candidate);if(conflicts.length){$('#shortcutConflict',p).textContent=`Conflitos no mesmo contexto: ${conflicts.map(c=>`${c[0]} e ${c[1]} usam ${c[2]}`).join('; ')}`;return}for(const [action,value] of Object.entries(candidate))await invoke('set_setting',{req:{key:shortcutSettingKey(action),value}});ctx.state.boot.settings.shortcuts={...(ctx.state.boot.settings.shortcuts||{}),...candidate};ctx.state.boot.settings.shortcutNew=candidate.newMessage;ctx.state.boot.settings.shortcutCommand=candidate.commandCenter;ctx.state.boot.settings.shortcutSettings=candidate.settings;window.dispatchEvent(new CustomEvent('tcs-shortcuts-changed'));toast('Atalhos salvos. Tooltips e comandos usarão os novos valores imediatamente.');page('shortcuts')}}
