 const openFeedback=()=>{const m=modal('Enviar sugestão ou informar erro',`<p class="settingsPanelIntro">Este recurso funciona mesmo sem nenhuma conta cadastrada no TCS Mail. O envio é preparado para <b>tcsmail@thecreativesolver.com</b> usando o aplicativo de e-mail padrão do sistema.</p>${field('Tipo','<select id="feedbackType"><option value="suggestion">Sugestão</option><option value="bug">Informar erro</option><option value="other">Outro</option></select>')}${field('Título','<input id="feedbackTitle" maxlength="160">')}${field('Descrição','<textarea id="feedbackBody" rows="8" placeholder="Descreva o que aconteceu ou sua sugestão. Não inclua senhas nem tokens."></textarea>')}<label class="settingsToggle"><input id="feedbackDiag" type="checkbox" checked> Incluir versão e plataforma (sem mensagens, senhas ou tokens)</label><div id="feedbackState" class="diagnosticResult"></div><footer class="modalActions"><button id="feedbackCopy">Copiar mensagem</button><button id="feedbackSend" class="primary">Preparar envio</button></footer>`,{wide:true,resizable:true,persistKey:'feedback'});const build=()=>{const type=$('#feedbackType',m.root).value,label=type==='bug'?'Erro':type==='suggestion'?'Sugestão':'Contato',title=$('#feedbackTitle',m.root).value.trim()||label,diag=$('#feedbackDiag',m.root).checked?`\n\n---\nTCS Mail ${appVersion}\nPlataforma: ${ctx.state.boot.platform}\nIdioma: ${ctx.state.boot.settings.uiLanguage||'system'}`:'',body=$('#feedbackBody',m.root).value.trim()+diag;return{subject:`[TCS Mail] ${label}: ${title}`,body}};$('#feedbackCopy',m.root).onclick=async()=>{const x=build();await navigator.clipboard.writeText(`${x.subject}\n\n${x.body}`);toast('Mensagem de feedback copiada.')};$('#feedbackSend',m.root).onclick=async()=>{const x=build();if(!$('#feedbackBody',m.root).value.trim())return toast('Descreva a sugestão ou o erro antes de continuar.');const uri=`mailto:tcsmail@thecreativesolver.com?subject=${encodeURIComponent(x.subject)}&body=${encodeURIComponent(x.body)}`;try{await invoke('open_external_url',{url:uri});$('#feedbackState',m.root).className='diagnosticResult ok';$('#feedbackState',m.root).textContent='Mensagem preparada no aplicativo de e-mail padrão. Revise e envie por lá.'}catch(e){await navigator.clipboard.writeText(`${x.subject}\n\n${x.body}`).catch(()=>{});$('#feedbackState',m.root).className='diagnosticResult fail';$('#feedbackState',m.root).textContent='Não foi possível abrir um aplicativo de e-mail. A mensagem foi copiada para a área de transferência; envie-a para tcsmail@thecreativesolver.com.'}}};
